INSERT INTO `t_polymarket_market` VALUES (4, 'will-england-win-the-2026-fifa-world-cup-937', '558935', '0x375409bc5eeeff961e82b479caeccc20f33d15738e5bce1186d628aa3d9dfb1f', '2026-fifa-world-cup-winner-595', '2026 FIFA World Cup Winner ', 'Will England win the 2026 FIFA World Cup?', '[\"115556263888245616435851357148058235707004733438163639091106356867234218207169\",\"77121637225348873006259930776623502125079210522997384841464684944292365296940\"]', '[\"Yes\",\"No\"]', '2026-07-20 08:00:00', 0, NULL, NULL, NULL, NULL, 1, 22.700000, 0.227000, 11.350000, 100.00000000, 0.00000000, 0.00000000, NULL, NULL, '{\"sourceUrl\":\"https://gamma-api.polymarket.com/markets/slug/will-england-win-the-2026-fifa-world-cup-937\",\"market\":{\"featured\":false,\"volume24hr\":159823.36436300003,\"umaBond\":\"500\",\"endDate\":\"2026-07-20T00:00:00Z\",\"holdingRewardsEnabled\":true,\"liquidity\":\"1280125.26318\",\"endDateIso\":\"2026-07-20\",\"marketMakerAddress\":\"\",\"volume1wkClob\":1862453.6886949982,\"createdAt\":\"2025-07-02T16:54:41.473096Z\",\"approved\":true,\"conditionId\":\"0x375409bc5eeeff961e82b479caeccc20f33d15738e5bce1186d628aa3d9dfb1f\",\"volume1yr\":18117084.350247975,\"outcomes\":\"[\\\"Yes\\\", \\\"No\\\"]\",\"lastTradePrice\":0.113,\"funded\":false,\"clobRewards\":[{\"rewardsAmount\":0,\"conditionId\":\"0x375409bc5eeeff961e82b479caeccc20f33d15738e5bce1186d628aa3d9dfb1f\",\"endDate\":\"2500-12-31\",\"assetAddress\":\"0xc011a7e12a19f7b1f670d46f03b03f3342e82dfb\",\"rewardsDailyRate\":0.001,\"id\":\"377519\",\"startDate\":\"2026-05-19\"}],\"enableOrderBook\":true,\"id\":\"558935\",\"volume1mo\":5989961.674857006,\"pagerDutyNotificationEnabled\":false,\"slug\":\"will-england-win-the-2026-fifa-world-cup-937\",\"events\":[{\"featured\":true,\"volume24hr\":9419822.979772,\"openInterest\":14489456.571105,\"endDate\":\"2026-07-20T00:00:00Z\",\"icon\":\"https://polymarket-upload.s3.us-east-2.amazonaws.com/2026-fifa-world-cup-winner-595-8rgoVIZnbKgL.png\",\"description\":\"This market will resolve according to the national team that wins the 2026 FIFA World Cup.\\n\\nIf at any point it becomes impossible for this team to win the FIFA World Cup based on the rules of FIFA (e.g., they are eliminated in the knockout stage), this market will resolve immediately to “No”.\\n\\nIf the 2026 FIFA World Cup is permanently canceled or has not been completed by October 13, 2026, 11:59 PM this market will resolve to “Other”.\\n\\nThe primary resolution source will be official information from FIFA, however, a consensus of credible reporting may also be used.\",\"liquidity\":262129619.85879,\"title\":\"2026 FIFA World Cup Winner \",\"eventMetadata\":{\"context_updated_at\":\"2026-05-20T05:46:14.097Z\",\"context_requires_regen\":true,\"context_description\":\"European powerhouses France and Spain lead the 2026 FIFA World Cup winner market due to deep squads, strong recent Nations League and qualifying form, and youth pipelines that minimize separation among top contenders. Spain sustains attacking potency despite Lamine Yamal\'s hamstring recovery concerns, while France blends experience with athleticism. England adds pressure through roster balance and venue familiarity in North America. Trailing sides like Brazil and Argentina navigate transitional phases and tougher paths, keeping probabilities tightly clustered as traders weigh historical precedents, group-stage schedules, and late injury updates ahead of the June opener.\"},\"volume1wk\":84305749.9079161,\"featuredOrder\":16,\"archived\":false,\"createdAt\":\"2025-07-02T16:54:39.838289Z\",\"volume1yr\":1035383851.694887,\"enableOrderBook\":true,\"liquidityClob\":262129619.85879,\"sortBy\":\"price\",\"id\":\"30615\",\"volume1mo\":346690546.46524376,\"gmpChartMode\":\"default\",\"negRiskAugmented\":true,\"slug\":\"2026-fifa-world-cup-winner-595\",\"updatedAt\":\"2026-05-20T05:57:18.94044Z\",\"cumulativeMarkets\":false,\"deployingTimestamp\":\"2025-07-02T22:06:00.953755Z\",\"image\":\"https://polymarket